{[Fact] public void PaperKeepsReplayCarrierAndMemoryBindingOwnerLocal(){string p=File.ReadAllText(Path.Combine(Root(),"ResearchPaper","section","md base","3_Architectural_Overview_and_Frontend_Contract.md"));Assert.Contains("For `ReplayToken`, default or unbound state",p,StringComparison.Ordinal);Assert.Contains("not an issued attempt, request, resource token",p,StringComparison.Ordinal);Assert.Contains("replay owner retains capture, validation, rollback",p,StringComparison.Ordinal);Assert.Contains("No generic conversion",p,StringComparison.Ordinal);}private static string Root(){DirectoryInfo? c=new(AppContext.BaseDirectory);while(c is not null){if(Directory.Exists(Path.Combine(c.FullName,"ResearchPaper")))return c.FullName;c=c.Parent;}throw new DirectoryNotFoundException();}}
